const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;

// Secret validation (opcional)
const secret = process.env.N8N_WEBHOOK_SECRET;
if (secret) {
  const incomingSecret = (input.headers || {})['x-webhook-secret'];
  if (incomingSecret !== secret) throw new Error('Webhook secret inválido');
}

const eventType  = body.event_type    || body.eventType    || '';
const entityType = body.entity_type   || body.entityType   || '';
const entityId   = body.entity_id     || body.entityId     || '';
const dealerId   = body.dealer_id     || body.dealerId     || '';
const vehicleId  = body.vehicle_id    || body.vehicleId    || '';
const data       = body.data          || body.payload      || body;
const createdAt  = body.created_at    || new Date().toISOString();

const SUPPORTED_EVENTS = [
  'lead.created',
  'custom_request.created',
  'search_alert.created',
  'vehicle.approved',
  'vehicle.rejected',
  'vehicle.submitted_for_review'
];

if (!SUPPORTED_EVENTS.includes(eventType)) {
  return [{ json: { ok: false, reason: `event_type no soportado: ${eventType}`, eventType } }];
}

return [{
  json: {
    ok: true,
    eventType,
    entityType,
    entityId,
    dealerId,
    vehicleId,
    data,
    createdAt,
    rawBody: body
  }
}];

const ev = $input.first().json;
const d = ev.data || {};
const MAIL_FROM  = process.env.MAIL_FROM  || 'Black Label Market <no-reply@blacklabelmarket.es>';
const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';

// Email de confirmación al comprador
const buyerName    = d.buyer_name    || d.name    || 'Interesado';
const buyerEmail   = d.buyer_email   || d.email   || '';
const vehicleTitle = d.vehicle_title || d.title   || 'el vehículo';
const dealerName   = d.dealer_name   || d.showroom || 'el concesionario';

const buyerEmailHtml = `<p>Hola ${buyerName},</p>
<p>Tu mensaje de contacto sobre <strong>${vehicleTitle}</strong> ha sido enviado correctamente a <strong>${dealerName}</strong>.</p>
<p>El concesionario se pondrá en contacto contigo en breve.</p>
<p>El equipo de Black Label Market</p>`;

// Email de notificación al dealer
const dealerEmail = d.dealer_email || '';
const dealerEmailHtml = `<p>Has recibido un nuevo lead en Black Label Market.</p>
<p><strong>Vehículo:</strong> ${vehicleTitle}<br>
<strong>Interesado:</strong> ${buyerName}<br>
<strong>Email:</strong> ${buyerEmail}<br>
<strong>Mensaje:</strong> ${(d.message || '').slice(0, 500)}</p>
<p><a href="${MARKET_URL}/dashboard/oportunidades">Ver en tu panel →</a></p>`;

const slackText = `*📩 Nuevo lead*\n\n*Vehículo:* ${vehicleTitle}\n*Comprador:* ${buyerName} (${buyerEmail})\n*Dealer:* ${dealerName}`;

return [{
  json: {
    ...ev,
    buyerName, buyerEmail, dealerName, dealerEmail, vehicleTitle,
    buyerEmailPayload:  buyerEmail  ? { from: MAIL_FROM, to: [buyerEmail],  subject: 'Tu consulta ha sido enviada — Black Label Market', html: buyerEmailHtml }  : null,
    dealerEmailPayload: dealerEmail ? { from: MAIL_FROM, to: [dealerEmail], subject: `Nuevo lead: ${vehicleTitle}`, html: dealerEmailHtml } : null,
    slackText
  }
}];

const ev = $input.first().json;
const d = ev.data || {};
const MAIL_FROM  = process.env.MAIL_FROM  || 'Black Label Market <no-reply@blacklabelmarket.es>';
const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';

const name     = d.name  || d.contact?.name  || 'Interesado';
const email    = d.email || d.contact?.email || '';
const brand    = d.brand    || d.marca    || '';
const model    = d.model    || d.modelo   || '';
const budget   = d.budget_text || d.budget || '';
const timeline = d.timeframe  || d.timeline || '';

const vehicleDesc = [brand, model].filter(Boolean).join(' ') || 'vehículo a medida';

const html = `<p>Hola ${name},</p>
<p>Hemos recibido tu solicitud de <strong>${vehicleDesc}</strong>.</p>
<p>Nuestro equipo analizará tu petición y contactará con los mejores concesionarios especializados. Te contactaremos en un plazo de 24-48 horas laborables.</p>
${budget ? '<p><strong>Presupuesto:</strong> ' + budget + '</p>' : ''}
${timeline ? '<p><strong>Plazo:</strong> ' + timeline + '</p>' : ''}
<p>El equipo de Black Label Market</p>`;

return [{
  json: {
    ...ev,
    name, email,
    emailPayload: email ? {
      from: MAIL_FROM, to: [email],
      subject: `Solicitud recibida: ${vehicleDesc} — Black Label Market`,
      html
    } : null
  }
}];

const ev = $input.first().json;
const d = ev.data || {};
const MAIL_FROM  = process.env.MAIL_FROM  || 'Black Label Market <no-reply@blacklabelmarket.es>';
const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';

const email   = d.user_email || d.email || '';
const name    = d.user_name  || d.name  || 'Usuario';
const brand   = d.criteria?.brand  || d.brand  || '';
const model   = d.criteria?.model  || d.model  || '';
const maxPrice = d.criteria?.max_price || d.max_price || '';

const criteriaDesc = [brand, model, maxPrice ? `hasta ${maxPrice}€` : ''].filter(Boolean).join(' · ') || 'criterios guardados';

const html = `<p>Hola${name !== 'Usuario' ? ' ' + name : ''},</p>
<p>Tu alerta de búsqueda ha quedado guardada en Black Label Market.</p>
<p><strong>Criterios:</strong> ${criteriaDesc}</p>
<p>Te notificaremos por email cada vez que publiquemos un vehículo que encaje con tu búsqueda.</p>
<p>El equipo de Black Label Market</p>`;

return [{
  json: {
    ...ev,
    name, email,
    emailPayload: email ? {
      from: MAIL_FROM, to: [email],
      subject: 'Alerta guardada — Black Label Market',
      html
    } : null
  }
}];

