const vehicleSlug  = d.vehicle_slug  || d.slug  || '';
const vehicleUrl   = vehicleSlug ? `${MARKET_URL}/coches/${vehicleSlug}` : `${MARKET_URL}/dashboard/inventario`;

const html = `<p>Hola,</p>
