<p><a href="${vehicleUrl}">Ver ficha publicada →</a></p>
<p>Los posibles compradores ya pueden contactarte a través de la ficha.</p>
<p>El equipo de Black Label Market</p>`;

return [{
  json: {
    ...ev,
    dealerEmail, dealerName, vehicleTitle,
    emailPayload: dealerEmail ? {
      from: MAIL_FROM, to: [dealerEmail],
      subject: `Vehículo aprobado: ${vehicleTitle}`,
      html
    } : null
  }
}];

const ev = $input.first().json;
const d = ev.data || {};
const MAIL_FROM  = process.env.MAIL_FROM  || 'Black Label Market <no-reply@blacklabelmarket.es>';
const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';

const dealerEmail  = d.dealer_email  || '';
const vehicleTitle = d.vehicle_title || d.title || 'Tu vehículo';
const reason       = d.rejection_reason || d.reason || 'No cumple los requisitos editoriales actuales de la plataforma.';

const html = `<p>Hola,</p>
<p>Hemos revisado la ficha de <strong>${vehicleTitle}</strong> y en este momento no podemos publicarla en Black Label Market.</p>
<p><strong>Motivo:</strong> ${reason}</p>
<p>Si tienes dudas o quieres hacer ajustes, puedes acceder a tu panel y editar la ficha.</p>
<p><a href="${MARKET_URL}/dashboard/inventario">Acceder a tu inventario →</a></p>
<p>El equipo de Black Label Market</p>`;

return [{
  json: {
    ...ev,
    dealerEmail, vehicleTitle,
    emailPayload: dealerEmail ? {
      from: MAIL_FROM, to: [dealerEmail],
      subject: `Ficha no aprobada: ${vehicleTitle}`,
      html
    } : null
  }
}];
